-- Generated by `pnpm decisions:seed` from docs/planning/decisions.md (decision 191): the log's
-- entries as decisions, numbered as in the log, active unless a later entry replaces them.
-- Do not edit by hand.
insert into public.decisions
  (number, statement, reason, status, decided_by_name, decided_at, origin, origin_ref)
overriding system value
values
  (223, 'How slice 4.5 is built (`slice-4-5.md`). The web app''s home shows, for a signed-in person, their brief for now (as `/brief`), the jobs with this month''s spend against their caps, the team''s scorecard and the agents at work, each read on its own so one failing does not blank the page. The scorecard (`GET /v1/scorecard`) counts, from the records only, this week (Monday 00:00 UTC to now) against last: decisions made active, conflicts settled, waits ended, changes started, pull requests reviewed by the checker and goal tickets merged. Pull requests merged outside goals are not counted', 'Nothing records when a pull request merges unless a goal reads it, and a count that misses most merges would mislead. The scorecard is the team''s, never per person, so it does not rank people. Counts from the records alone keep the home page from calling Slack, GitHub or the tracker', 'active', 'the owner', '2026-11-26T00:00:00Z', 'import', '223'),
  (224, 'Changes to slice 4.5 after an independent review, before it merged. Changes started counts each change once, in the week its first brief was started; a later brief of the same change is more work on it, not another change. A job''s last wake''s outcome is the outcome of the wake at its last wake''s time, or none when that wake is no longer kept, never an older wake''s. Left as they are: imports from the decision log count as decisions made for every workspace, as the decisions page shows them to everyone; the decisions page shows every decision, those from private channels included, to anyone signed in, so the narrower count reveals nothing it hides; the checker''s reviews count for the workspace that has the checker job, which is only the deployment''s own; the jobs'' response is read strictly, so a web app and an API of different slices do not read each other''s jobs until both have deployed, as at any change to a response', 'The review found that a change with more than one brief was counted once for each, so "changes started" counted follow-up work as new changes, and that a job whose last wake had been pruned (a silent wake, after 14 days) showed an older wake''s outcome beside its last wake''s time. Each now has a test', 'active', 'the owner', '2026-11-27T00:00:00Z', 'import', '224')
on conflict (origin, origin_ref) where origin_ref is not null do nothing;
